"""Independently recompute diagnostic masks from raw JSONL using only stdlib.

No experiment implementation or analyzer is imported. Derived analysis files
are not inputs to the calculation. An optional discovery receipt is compared
only after the raw calculation has completed.
"""
import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path
import sys

EXPECTED = {
    'fanout': {'names': ['patient', 'measurement', 'reading', 'diagnosis', 'severity', 'drug',
        'route', 'language', 'procedure', 'author', 'department', 'status'],
        'rows': 1152000, 'checksum': '3123987218479850048',
        'querySha256': '9cffa2dc37bbb1e2743442b228d5ab9a41115bf7c4a6667506231fbda3bfc301',
        'canonicalGraphSha256': 'cf637a7e80dbd9468d7e8b04116da072f726038282dfab15380c267c8cc82e9b',
        'rootMain': 'org.eclipse.rdf4j.sail.lmdb.benchmark.OptionalFanoutExperiment',
        'rootReadPhase': 'after-original-harness-main'},
    'shared-tail': {'names': ['s', 'a', 'l0', 'l1', 'r0', 'r1'],
        'rows': 1048576, 'checksum': '8327963502356915200',
        'querySha256': '570d85a6fd11ecabae385744a2137f45aad5c9e53bf74dd50b2de69f3c2a4b76',
        'canonicalGraphSha256': '59218d96a3c4c1cd3a2634c72174b0f44f3a7415d6cae4c944b1a54ed9506621',
        'rootMain': 'org.eclipse.rdf4j.sail.lmdb.benchmark.SharedSelectionExperiment',
        'rootReadPhase': 'after-shared-selection-harness-main'}}
ORDINARY_OUTCOMES = ['ordinaryIdMiss', 'ordinaryHit', 'ordinaryWeakMiss', 'ordinaryWitnessMiss']
FACTOR_OUTCOMES = ['factorInitialMiss', 'factorPageMiss', 'factorCellMiss', 'factorWeakMiss',
                   'factorWitnessMiss', 'factorHit']
PUBLICATION_OUTCOMES = ['publicationInitialMiss', 'publicationOwnerMiss', 'publicationPageMiss',
                        'publicationComplete', 'publicationSkipped']
COUNTERS = ['find', *ORDINARY_OUTCOMES, 'factorLookup', *FACTOR_OUTCOMES, 'publicationCall',
    *PUBLICATION_OUTCOMES, 'publicationWrite', 'pageAttempt', 'pageAdmitted', 'pageRefused',
    'coordinateAttempt', 'coordinateSuccess', 'rememberCall', 'pageBytesGranted',
    'pageBytesReleased', 'pagesReleased']


def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def read_jsonl(path, sources):
    sources[str(path)] = digest(path)
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def owner_totals(path, query, names, limit, sources):
    records = read_jsonl(path, sources)
    require(records and records[0]['type'] == 'owner', 'Missing owner header: ' + str(path))
    header = records[0]
    require(header['extraWeakDereferences'] == 0 and header['queryLimit'] == limit,
            'Unexpected dereference or memory-limit declaration')
    targets = [r for r in records[1:] if r['type'] == 'target']
    pages = [r for r in records[1:] if r['type'] == 'page']
    require(len(records) == 1 + len(targets) + len(pages), 'Unrecognized owner record')
    by_index = {r['target']: r for r in targets}
    require(len(targets) == len(names) and set(by_index) == set(range(len(names))),
            'Duplicate/missing target index')
    require(all(by_index[i]['name'] == name and by_index[i]['canonical'] == i for i, name in enumerate(names)),
            'This reconciliation requires the expected projection and identity aliases')
    require(header['pageCount'] == len(pages), 'Header and raw page count differ')
    page_counts, page_bytes, occupied_counts = Counter(), Counter(), Counter()
    keys = set()
    for page in pages:
        index = page['target']
        require(index in by_index and by_index[index]['canonical'] == index, 'Page target is not a canonical bank')
        key = (index, page['namespace'], page['group'], page['parent'], page['column'], page['pageIndex'])
        require(key not in keys, 'Duplicate complete factor-page key')
        keys.add(key)
        bits = int(page['occupiedMask'])
        require(0 <= bits < 2**64 and bits.bit_count() == page['occupied'], 'Invalid occupancy mask')
        require(page['claim'] == 16384 and 0 <= page['occupied'] <= 64, 'Unexpected original page layout')
        page_counts[index] += 1
        page_bytes[index] += page['claim']
        occupied_counts[index] += page['occupied']
    banks = {}
    for index in range(len(names)):
        target = by_index[index]
        require(all(isinstance(target[k], int) and target[k] >= 0 for k in COUNTERS), 'Invalid counter value')
        require(target['find'] == sum(target[k] for k in ORDINARY_OUTCOMES), 'Ordinary lookup partition differs')
        require(target['factorLookup'] == target['find'] - target['ordinaryHit'], 'Ordinary/factor boundary differs')
        require(target['factorLookup'] == sum(target[k] for k in FACTOR_OUTCOMES), 'Factor lookup partition differs')
        require(target['publicationCall'] == sum(target[k] for k in PUBLICATION_OUTCOMES), 'Publication exit partition differs')
        require(target['publicationWrite'] <= target['publicationComplete'], 'More writes than completed publications')
        require(target['coordinateSuccess'] <= target['coordinateAttempt'], 'Coordinate success exceeds attempts')
        require(target['pageAttempt'] == target['pageAdmitted'] + target['pageRefused'], 'Admission partition differs')
        require(target['pageAdmitted'] == target['pagesReleased'], 'Unreleased admitted page')
        require(target['pageBytesGranted'] == target['pageBytesReleased'] == target['pageAdmitted'] * 16384,
                'Page granted/released charge differs')
        require(page_counts[index] <= target['pageAdmitted'], 'Final table exceeds lifetime admissions')
        canonical = target['canonical']
        bank = banks.setdefault(canonical, {'canonicalIndex': canonical, 'name': names[canonical],
            'aliasNames': [], 'totals': Counter(), 'finalPages': 0, 'finalPageBytes': 0,
            'finalOccupiedCells': 0, 'allAdmittedPagesPresentAtFinalClose': True})
        bank['aliasNames'].append(target['name'])
        bank['totals'].update({k: target[k] for k in COUNTERS})
        bank['finalPages'] += page_counts[index]
        bank['finalPageBytes'] += page_bytes[index]
        bank['finalOccupiedCells'] += occupied_counts[index]
        bank['allAdmittedPagesPresentAtFinalClose'] &= page_counts[index] == target['pageAdmitted']
    totals = {key: sum(t[key] for t in targets) for key in COUNTERS}
    reads, resolvers = query['bindingReads'], query['counters']['lazyValueCalls']
    require(reads == query['rows'] * len(names) == totals['find'], 'Binding/find reconciliation failed')
    require(totals['ordinaryHit'] + totals['factorHit'] + resolvers == reads, 'Hit/resolver reconciliation failed')
    require(totals['rememberCall'] == resolvers, 'Remember/resolver reconciliation failed')
    require(totals['publicationCall'] == totals['ordinaryHit'] + totals['rememberCall'],
            'Publication entry reconciliation failed for these fully bound coordinate fixtures')
    current_claim = header['ordinaryClaim'] + header['directoryClaim'] + header['memoClaim'] + sum(page_bytes.values())
    require(header['ledgerBeforeClose'] >= current_claim, 'Owned close-time claims exceed query ledger')
    require(header['ledgerBeforeClose'] >= header['ledgerAfterClose'] >= 0, 'Invalid owner close ledger')
    return {'owner': header['owner'], 'iteration': query['iteration'], 'stage': query['stage'],
        'rows': query['rows'], 'checksum': query['checksum'], 'bindingReads': reads, 'resolverCalls': resolvers,
        'totals': totals, 'banks': {bank['name']: bank for bank in banks.values()},
        'ledgerPeakBytes': query['ledgerPeakBytes'], 'ledgerBeforeOwnerClose': header['ledgerBeforeClose'],
        'ledgerAfterOwnerClose': header['ledgerAfterClose'], 'closeTimeOwnedClaims': current_claim,
        'closeTimeOtherQueryClaims': header['ledgerBeforeClose'] - current_claim,
        'pageChargeBytes': sum(page_bytes.values()), 'distinctPageKeys': len(keys),
        'storedOccupiedCells': sum(occupied_counts.values()),
        'pageGrantReleaseEquality': True, 'fullLookupResolverReconciliation': True}


def inspect_fixture(suite, name, plan, sources):
    expected = EXPECTED[name]
    folder = suite / 'runs' / name
    data = read_jsonl(folder / 'samples.jsonl', sources)
    require(len(data) == 5 and data[0]['type'] == 'metadata', 'Expected metadata and four diagnostic queries')
    metadata, queries = data[0], data[1:]
    require(metadata['projectedNames'] == expected['names'] and metadata['expectedRows'] == expected['rows']
            and metadata['expectedChecksum'] == expected['checksum']
            and metadata['querySha256'] == expected['querySha256']
            and metadata['canonicalGraphSha256'] == expected['canonicalGraphSha256'], 'Fixture identity changed')
    require(metadata['warmup'] == 3 and metadata['measurementsToRun'] == 1
            and metadata['maxHeapBytes'] == 1073741824 and metadata['globalLedgerLimitBytes'] == 1073741824
            and metadata['perQueryLedgerLimitBytes'] == plan['queryLimitBytes'], 'Diagnostic settings changed')
    require(metadata['source'] == plan['sourceIdentity'] and metadata['arm'] == plan['name']
            and metadata['consumption'] == 'full' and metadata['nativeEvaluation']
            and metadata['directAdjacency'] and metadata['directAdjacencyMode'] == 'PREFER', 'Diagnostic route settings changed')
    page_files = sorted((folder / 'page-records').glob('owner-*.jsonl'), key=lambda p: int(p.stem.split('-')[1]))
    require([p.name for p in page_files] == ['owner-1.jsonl', 'owner-2.jsonl', 'owner-3.jsonl', 'owner-4.jsonl'],
            'Owner files do not match the four query sequence')
    result = []
    for i, (query, page_file) in enumerate(zip(queries, page_files, strict=True)):
        require(query['iteration'] == i - 3 and query['stage'] == ('warmup' if i < 3 else 'measurement'),
                'Diagnostic chronology changed')
        require(query['valid'] and query['complete'] and query['rows'] == expected['rows']
                and query['checksum'] == expected['checksum'] and query['rowCountValid']
                and query['checksumValid'] and query['partialMembershipValid'], 'Result oracle failed')
        if name == 'shared-tail':
            require(query['exactBagValid'], 'Exact shared-tail bag oracle failed')
        require(query['ledgerBeforeBytes'] == query['ledgerAfterBytes'] == 0 and query['ledgerReleased'], 'Ledger leak')
        counters, adjacency = query['counters'], query['adjacency']
        require(query['autoRequested'] and query['auto'] and query['successfulSelections']
                and all('forced' not in route['mode'] for route in query['successfulSelections'])
                and counters['irOpened'] == counters['semanticNativeCompiles'] == 1
                and counters['irRows'] == expected['rows'], 'Normal AUTO native route failed')
        if i == 3:
            require(counters['compiledBinds'] == 1 and counters['interpretedBinds']
                == counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0,
                'Observed diagnostic query is not compiled-only native IR')
        require(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE' and adjacency['lookupHits'] > 0
                and adjacency['currentRevisionBefore'] == adjacency['appliedRevisionBefore']
                == adjacency['currentRevisionAfter'] == adjacency['appliedRevisionAfter'], 'Adjacency changed')
        owner = owner_totals(page_file, query, expected['names'], plan['queryLimitBytes'], sources)
        require(owner['owner'] == i + 1, 'Query/owner sequence differs')
        result.append(owner)
    audit_file = folder / 'root-host-audit.json'
    sources[str(audit_file)] = digest(audit_file)
    audit = json.loads(audit_file.read_text())
    require(audit['harnessReturned'] and audit['harnessFailureClass'] is None and audit['hostedGenericTotal'] == 0
            and audit['semanticNativeCompilesTotal'] == 4 and audit['harnessMain'] == expected['rootMain']
            and audit['readPhase'] == expected['rootReadPhase'], 'Outer-root qualification failed')
    decisions = {}
    for target in expected['names']:
        history = [query['banks'][target]['totals'] for query in result]
        checks = {'admittedPagesInEveryQuery': all(t['pageAdmitted'] > 0 for t in history),
            'completedPublicationsInEveryQuery': all(t['publicationComplete'] > 0 for t in history),
            'noFactorHitInAnyQuery': not any(t['factorHit'] for t in history),
            'noFactorWeakMissInAnyQuery': not any(t['factorWeakMiss'] for t in history),
            'noFactorWitnessMissInAnyQuery': not any(t['factorWitnessMiss'] for t in history)}
        decisions[target] = {'candidate': all(checks.values()), 'checks': checks}
    return {'queries': result, 'decisions': decisions,
        'candidateCanonicalNames': sorted(n for n, d in decisions.items() if d['candidate']),
        'noFactorAdmissionRefusals': all(q['totals']['pageRefused'] == 0 for q in result),
        'pageGrantReleaseEqualityEveryQuery': True, 'lookupResolverReconciliationEveryQuery': True,
        'queryLedgerEndpointsZeroEveryQuery': True}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--suite', type=Path, required=True)
    parser.add_argument('--discovery', type=Path)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    suite = args.suite.resolve(strict=True)
    plan_file = suite / 'protocol.json'
    sources = {str(plan_file): digest(plan_file)}
    plan = json.loads(plan_file.read_text())
    require(plan['warmup'] == 3 and plan['iterations'] == 1 and plan['transport'] == 'dense'
            and plan['consumption'] == 'full', 'Unexpected discovery protocol')
    fixtures = {name: inspect_fixture(suite, name, plan, sources) for name in plan['fixtures']}
    match = None
    if args.discovery:
        discovery = args.discovery.resolve(strict=True)
        sources[str(discovery)] = digest(discovery)
        claim = json.loads(discovery.read_text())
        require(set(claim['fixtures']) == set(fixtures), 'Claim and raw fixtures differ')
        match = all(sorted(claim['fixtures'][name]['candidateCanonicalNames']) == f['candidateCanonicalNames']
                    for name, f in fixtures.items())
        require(match, 'Published mask decisions differ from independent raw calculation')
    record = {'format': 1, 'valid': True, 'independentImplementation': 'Python stdlib; no analyzer or runner imports',
        'scriptSha256': digest(__file__), 'suite': str(suite), 'queryLimitBytes': plan['queryLimitBytes'],
        'mask': plan['mask'], 'fixtures': fixtures, 'sourceFiles': sources, 'publishedDiscoveryMatches': match,
        'javaProcessesLaunched': 0, 'performanceInference': False,
        'limits': 'Observed full-consumption queries only; no generic no-replay proof. Occupancy counts non-null weak-reference cells. Explicit lifetime grants/releases cover pages; other claims are close-time snapshots.'}
    with args.output.open('x') as stream:
        json.dump(record, stream, indent=2, sort_keys=True)
        stream.write('\n')
    print(json.dumps({'valid': True, 'masks': {n: f['candidateCanonicalNames'] for n, f in fixtures.items()},
        'matchesPublishedDiscovery': match, 'output': str(args.output)}))


if __name__ == '__main__':
    main()
